template:
fn first_word<'a, 'b>(
    s: ⟦slot1⟧,
    _delim: ⟦slot2⟧,
) -> &'a str {
    s.split(' ').next().unwrap_or("")
}

fn main() {
    let text = String::from("hello world");
    let mut delim = String::from(" ");
    let word = first_word(&text, &delim);
    delim.clear();
    println!("{word}");
}

tests:
#[test]
fn extracts_and_allows_mutation() {
    let text = String::from("rust language");
    let mut d = String::from(" ");
    let w = first_word(&text, &d);
    d.clear();
    assert_eq!(w, "rust");
}
